create table if not exists public.analytics_events (id uuid primary key default gen_random_uuid(),event_type text not null,user_id uuid references auth.users(id) on delete set null,visitor_id text,path text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists analytics_events_created_at_idx on public.analytics_events(created_at desc);create index if not exists analytics_events_event_type_idx on public.analytics_events(event_type);create index if not exists analytics_events_visitor_id_idx on public.analytics_events(visitor_id);
alter table public.analytics_events enable row level security;revoke all on public.analytics_events from anon,authenticated;grant all on public.analytics_events to service_role;notify pgrst,'reload schema';
